        return 0

    # Start comparing from the first character of the first word
    for i in range(len(words[0])):
        char = words[0][i]

        # Check if the current character matches the character in every other word
        for j in range(1, len(words)):
            if i == len(words[j]) or words[j][i] != char:
                return words[0][:i]

    return words[0]

