def maxSubArray(nums):
    if not nums:
        return None

    max_current = max_global = nums[0]
    start = 0

    for i in range(1, len(nums)):
        # If the current element makes the running sum negative,
        # we start a new subarray from this element.
        if nums[i] > max_current + nums[i]:
            max_current = nums[i]
            start = i
        else:
