from typing import List
import collections

def wordLadderLength(beginWord: str, endWord: str, wordList: List[str]) -> int:
    if endWord not in wordList:
        return 0

    # Convert all words to lowercase for uniformity
    wordList = [w.lower() for w in wordList]

    # Create a graph using adjacency lists
    graph = {word: [] for word in wordList}
    for i in range(len(wordList)):
        for j in range(i+1, len(wordList)):
            diff_count = sum(1 for c1, c2 in zip(wordList[i], wordList[j]) if c1 != c2)
            if diff_count == 1:
                graph[wordList[i]].append(wordList[j])
                graph[wordList[j]].append(wordList[i])

    queue = collections.deque([(beginWord, 1)])
    visited = set([beginWord])

    while queue:
        current_word, steps = queue.popleft()

        if current_word == endWord:
            return steps

        for neighbor in graph[current_word]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, steps + 1))

    return 0
```

This solution uses Breadth-First Search (BFS) to find the shortest path between two words in a given list of words. It constructs an adjacency list representation of the graph based on the difference in letters between adjacent words. The BFS algorithm explores all possible transformations step by step until it reaches the target word or exhausts all possibilities.

